def norm(cells):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    r0,c0=min(ys),min(xs); return tuple(sorted((y-r0,x-c0) for y,x in cells))
def rot(p): return [(b,1-a) for a,b in p]  # rotate 90 deg
def get_col(piece):
    n=norm(piece)
    if len(n)!=4: return None
    # determine orientation: which corner is missing
    h=max(y for y,_ in n); w=max(x for _,x in n)
    corners=[(0,0),(0,w-1),(h-1,0),(h-1,w-1)]
    m=[c for c in corners if c not in n][0]
    return {'tl':2,'tr':4,'bl':3,'br':6}.get(m, -1)
def solve(gi):
    H=len(gi);W=len(gi[0])
    out=[[gi[y][x] for x in range(W)] for y in range(H)]
    for y in range(H):
        for x in range(W):
            if gi[y][x]==8:
                pass
    # find all L-tromino orientations via local check: cell with exactly neighbors forming an L? Use connected components of size>=2 of 8s and check patterns
    def is_l(y,x,dy,dx):
        # L if the 2x2 block {(y,x),(y,x+1),(y+1,x),(y+1,x+1)} contains (y,x),(y,x+1),(y+1,x+1) with (y+1,x) also 8 -> tromino missing BR etc.
        s={(y+a,x+b) for a in range(2) for b in range(2)}
        cnt=sum(1 for c in s if gi[c[0]][c[1]]==8)
        if cnt==3:
            missing=(list(s)[cnt-1:])  # placeholder
            mc=[p for p in s if gi[p[0]][p[1]]!=8]
            if mc:
                mr=min(p[0] for p in mc); mc_=min(p[1] for p in mc)
                # orientation of missing corner relative to bounding box
                bb_y=min(r for r,_ in s); bb_x=min(c for _,c in s)
                miss=(mr-bb_y,mc_-bb_x)
                if miss==(0,0):return 'br'
                if miss==(0,1):return 'tr'
                if miss==(1,0):return 'bl'
                if miss==(1,1):return 'tl'
    for y in range(H-1):
        for x in range(W-1):
            for dy,dx in ((0,0),(0,1),(1,0)):
                col=is_l(y,x,dy,dx)
                if col is not None:
                    for a in range(2):
                        for b in range(2):
                            yy=y+dy+a; xx=x+dx+b
                            if (yy,xx) in {(y+a,y+x) for y in []}: pass
                    # paint the 3 cells of the L
                    s={(y+a,x+b) for a in range(2) for b in range(2)}
                    mc=[p for p in s if gi[p[0]][p[1]]==8 and p!=(y,y) for p in []][:0]
                    mc=[p for p in s if gi[p[0]][p[1]]!=8]
                    o=[p for p in s if gi[p[0]][p[1]]==8]
                    for yy,xx in o: out[yy][xx]={'br':1,'tr':4,'bl':3,'tl':2}[col]
    return out
